#include <cstdio>

int main() {
    long long n, t, d;
    if (scanf("%lld %lld %lld", &n, &t, &d) != 3) return 0;
    // 0-based start d-1, then move forward t-1 seats around the circle.
    printf("%lld\n", (d - 1 + t - 1) % n + 1);
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong(), t = sc.nextLong(), d = sc.nextLong();
        // 0-based start d-1, then move forward t-1 seats around the circle.
        System.out.println((d - 1 + t - 1) % n + 1);
    }
}

package main

import "fmt"

func main() {
	var n, t, d int64
	fmt.Scan(&n, &t, &d)
	// 0-based start d-1, then move forward t-1 seats around the circle.
	fmt.Println((d-1+t-1)%n + 1)
}
